#include "settings.hpp"
#include <algorithm>
#include <cstdlib>
#include <sstream>
#include <map>
namespace shining_saturn { namespace {
std::string trim(const std::string& s){const auto a=s.find_first_not_of(" \t\r");if(a==std::string::npos)return {};const auto b=s.find_last_not_of(" \t\r");return s.substr(a,b-a+1);}
int number(const std::map<std::string,std::string>& m,const char* k,int fallback){auto i=m.find(k);if(i==m.end())return fallback;char* e=nullptr;long v=std::strtol(i->second.c_str(),&e,10);return e&&*e=='\0'&&e!=i->second.c_str()&&v>=-2147483647L&&v<=2147483647L?static_cast<int>(v):fallback;}
bool boolean(const std::map<std::string,std::string>&m,const char*k,bool d){auto i=m.find(k);if(i==m.end())return d;if(i->second=="1"||i->second=="true")return true;if(i->second=="0"||i->second=="false")return false;return d;}
}
bool SettingsManager::validate(UserSettings& s){if(s.version!=1)return false;s.ui_scale=std::max(75,std::min(150,s.ui_scale));s.video_filter=std::max(0,std::min(3,s.video_filter));s.performance_preset=std::max(0,std::min(2,s.performance_preset));if(s.menu_volume<0)s.menu_volume=0;if(s.menu_volume>1)s.menu_volume=1;if(s.sort<SortMode::TitleAscending||s.sort>SortMode::YearDescending)s.sort=SortMode::TitleAscending;return true;}
bool SettingsManager::save(const std::string& path,const UserSettings& input)const{if(!storage_||path.empty())return false;UserSettings s=input;if(!validate(s))return false;std::ostringstream o;o<<"version="<<s.version<<"\nui_scale="<<s.ui_scale<<"\nvideo_filter="<<s.video_filter<<"\nperformance_preset="<<s.performance_preset<<"\nvsync="<<(s.vsync?1:0)<<"\nmenu_music="<<(s.menu_music?1:0)<<"\nmenu_volume="<<s.menu_volume<<"\nsort="<<static_cast<int>(s.sort)<<"\n";return storage_->write_text(path,o.str());}
bool SettingsManager::load(const std::string& path,UserSettings& out)const{if(!storage_||path.empty())return false;std::string text;if(!storage_->read_text(path,text))return false;std::map<std::string,std::string> m;std::istringstream in(text);std::string line;while(std::getline(in,line)){line=trim(line);if(line.empty()||line[0]=='#'||line[0]==';')continue;auto eq=line.find('=');if(eq==std::string::npos)continue;auto k=trim(line.substr(0,eq)),v=trim(line.substr(eq+1));if(!k.empty())m[k]=v;}if(m.find("version")==m.end())return false;UserSettings s;s.version=number(m,"version",-1);if(s.version!=1)return false;s.ui_scale=number(m,"ui_scale",100);s.video_filter=number(m,"video_filter",0);s.performance_preset=number(m,"performance_preset",0);s.vsync=boolean(m,"vsync",true);s.menu_music=boolean(m,"menu_music",true);auto vi=m.find("menu_volume");if(vi!=m.end()){char* e=nullptr;float f=std::strtof(vi->second.c_str(),&e);if(e&&*e=='\0'&&e!=vi->second.c_str())s.menu_volume=f;}int sort=number(m,"sort",0);s.sort=sort>=0&&sort<=3?static_cast<SortMode>(sort):SortMode::TitleAscending;if(!validate(s))return false;out=s;return true;}
}